-- 세트 541. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set541.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 541, '부팅 과정과 복구 기본: 부팅 순서·target·로그', '서버가 켜져서 로그인 가능한 상태가 되기까지의 순서(펌웨어, GRUB, 커널, systemd, target)를 익히고, 기본 target 을 확인·변경하고, rescue/emergency 의 차이를 이해합니다. journalctl -b·-k·-p 로 부팅 로그를 읽고, 커널 파라미터를 읽는 법과 부팅이 안 될 때 어디부터 볼지를 배웁니다.', 'linux-systemd', '리눅스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 541);
UPDATE quest_set SET display_order = 762, unit_id = (SELECT id FROM unit WHERE id = 59), icon = '🥾' WHERE id = 541;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 1, '전원을 켠 뒤 로그인 화면까지의 순서', '서버 전원을 켠 뒤 로그인 화면(서비스 시작)까지 일어나는 일을 먼저 일어나는 순서대로 놓으세요.', '소프트웨어가 하나도 없을 때 처음 도는 것이 무엇인지, 그 다음 단계가 무엇을 올려 주는지 한 단계씩 떠올려 보세요.', NULL, NULL, '[]', 'order', '["커널이 하드웨어를 인식하고 루트 파일시스템을 연다", "systemd(PID 1)가 시작된다", "펌웨어(UEFI/BIOS)가 하드웨어를 점검하고 부팅 장치를 찾는다", "systemd 가 기본 target 에 묶인 서비스들을 시작한다", "GRUB 이 커널을 골라 메모리에 올린다"]', NULL, '펌웨어 → GRUB → 커널 → systemd → target 순서입니다. 펌웨어가 부팅 장치의 부트로더(GRUB)를 실행하고, GRUB 이 커널을 올리고, 커널이 첫 프로세스로 systemd(PID 1)를 실행하며, systemd 가 기본 target 을 목표로 필요한 서비스를 차례로 올립니다. 어느 단계에서 멈췄는지 알면 어디를 고칠지 좁혀집니다. (GRUB 화면 전이면 펌웨어·디스크, 커널 메시지 뒤에 멈추면 커널·루트 파일시스템, 서비스 시작 중이면 systemd 와 유닛 쪽입니다.)', '[2, 4, 0, 1, 3]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 2, 'target 이란 무엇일까', 'systemd 에서 서버가 "어떤 상태까지 올라온 상태로 부팅할지"를 정하는 이름이 **target** 입니다. 옛 SysV 의 런레벨과 비슷한 개념입니다. 두 대표 target 에 대한 설명으로 알맞은 것은 무엇일까요?', '`multi-user` 는 여러 사용자가 터미널로 접속하는 상태, `graphical` 의 이름에 있는 단어를 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["`multi-user.target` 은 사용자가 한 명만 로그인할 수 있는 상태, `graphical.target` 은 여러 명이 로그인할 수 있는 상태다", "`multi-user.target` 은 화면(GUI) 없이 텍스트 로그인과 네트워크 서비스까지, `graphical.target` 은 그 위에 그래픽 로그인 화면까지 올린다", "`multi-user.target` 은 서버용이라 네트워크가 꺼져 있고, `graphical.target` 은 네트워크가 켜진 상태다", "두 target 은 이름만 다르고 시작하는 서비스는 완전히 같다"]', 1, '`graphical.target` 은 `multi-user.target` 을 포함하고 그래픽 로그인(디스플레이 매니저)을 더한 것입니다. 서버는 화면이 필요 없어서 보통 기본값을 `multi-user.target` 으로 두고 메모리·부팅 시간을 아낍니다. 둘 다 여러 사용자가 접속할 수 있고 네트워크도 켜집니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 3, '기본 target 확인하기', '이 서버는 부팅하면 어떤 target 까지 올라오도록 설정돼 있을까요? 기본 target 은 `systemctl` 로 바로 물어볼 수 있습니다.

지금 설정된 **기본 target 의 이름**을 **`/tmp/q3.txt`** 에 저장하세요. (결과는 `xxx.target` 한 줄입니다.)', '`systemctl` 하위 명령 중 이름이 `get-` 으로 시작하는 것이 기본 target 을 보여 줍니다. 출력을 `>` 로 파일에 저장합니다.', 'systemctl get-default > /tmp/q3.txt
cat /tmp/q3.txt

# 기본 target 은 부팅할 때 도달할 목표 상태. 이 파일에 graphical.target 이 적힌다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf\\nsystemctl set-default graphical.target >/dev/null 2>&1\\n"]', '["sh", "-c", "( [ -s /tmp/q3.txt ] ) && ( [ \\"$(cat /tmp/q3.txt)\\" = \\"$(systemctl get-default)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q3.txt ]"]}, {"label": "현재 기본 target 이 적혀 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q3.txt)\\" = \\"$(systemctl get-default)\\" ]"]}]', '[{"title": "systemd.special: target 유닛 설명", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.special.html"}, {"title": "journalctl 매뉴얼", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}, {"title": "bootup: 부팅 과정", "url": "https://www.freedesktop.org/software/systemd/man/latest/bootup.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 4, '기본 target 을 서버용으로 바꾸기', '이 서버는 지금 화면이 필요 없는데도 `graphical.target` 으로 부팅하도록 되어 있습니다. 다음 부팅부터 텍스트 서버 상태인 **`multi-user.target`** 으로 올라오도록 **기본 target 을 바꾸세요.**

(지금 켜져 있는 서비스를 끄는 작업이 아니라, **다음 부팅의 기본값**을 바꾸는 작업입니다.)', '`get-` 의 짝이 되는 하위 명령이 있습니다. 바꾼 뒤에는 `get-` 으로 다시 확인하세요. 내부적으로는 `/etc/systemd/system/default.target` 심볼릭 링크가 바뀝니다.', 'systemctl set-default multi-user.target
systemctl get-default
readlink /etc/systemd/system/default.target

# default.target 심볼릭 링크가 multi-user.target 을 가리키게 바뀐다. 현재 실행 중인 서비스는 그대로이고 다음 부팅부터 적용된다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf\\nsystemctl set-default graphical.target >/dev/null 2>&1\\n"]', '["sh", "-c", "( [ \\"$(systemctl get-default)\\" = multi-user.target ] ) && ( readlink /etc/systemd/system/default.target | grep -q multi-user.target )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "기본 target 이 multi-user.target 이다", "cmd": ["sh", "-c", "[ \\"$(systemctl get-default)\\" = multi-user.target ]"]}, {"label": "default.target 링크가 multi-user.target 을 가리킨다", "cmd": ["sh", "-c", "readlink /etc/systemd/system/default.target | grep -q multi-user.target"]}]', '[{"title": "systemd.special: target 유닛 설명", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.special.html"}, {"title": "journalctl 매뉴얼", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}, {"title": "bootup: 부팅 과정", "url": "https://www.freedesktop.org/software/systemd/man/latest/bootup.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 5, '지금 도달한 target 목록 보기', 'target 도 유닛의 한 종류라서 서비스처럼 목록을 볼 수 있습니다. 지금 **활성화된 target 들의 목록**을 **`/tmp/q5.txt`** 에 저장하세요. `multi-user.target` 과 `basic.target` 같은 이름이 보일 것입니다.

(`--type=target` 은 유닛 종류를 target 으로 거르는 옵션입니다. 페이저는 `--no-pager` 로 끕니다.)', '`systemctl list-units` 에 종류를 거르는 옵션을 붙입니다. 옵션 이름은 위 설명에 있습니다.', 'systemctl list-units --type=target --no-pager > /tmp/q5.txt
cat /tmp/q5.txt

# sysinit.target → basic.target → multi-user.target 처럼 단계별 목표가 쌓여 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf\\nsystemctl set-default graphical.target >/dev/null 2>&1\\n"]', '["sh", "-c", "( [ -s /tmp/q5.txt ] ) && ( grep -q multi-user.target /tmp/q5.txt ) && ( grep -q basic.target /tmp/q5.txt ) && ( ! grep -q \\"\\\\.service\\" /tmp/q5.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q5.txt ]"]}, {"label": "multi-user.target 이 있다", "cmd": ["sh", "-c", "grep -q multi-user.target /tmp/q5.txt"]}, {"label": "basic.target 이 있다", "cmd": ["sh", "-c", "grep -q basic.target /tmp/q5.txt"]}, {"label": "service 유닛은 섞이지 않았다", "cmd": ["sh", "-c", "! grep -q \\"\\\\.service\\" /tmp/q5.txt"]}]', '[{"title": "systemd.special: target 유닛 설명", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.special.html"}, {"title": "journalctl 매뉴얼", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}, {"title": "bootup: 부팅 과정", "url": "https://www.freedesktop.org/software/systemd/man/latest/bootup.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 6, 'target 이 무엇에 묶여 있는지 보기', 'target 은 "이 서비스들이 모여야 도달"이라는 묶음이라서 **의존 관계의 나무**로 볼 수 있습니다. `graphical.target` 이 도달하려면 어떤 것들이 필요한지 나무를 **`/tmp/q6.txt`** 에 저장하세요. 안에 `multi-user.target` 이 한 단계 아래에 보이면 맞습니다.', '`systemctl` 에 ''무엇에 의존하는지 나무로 보여 주는'' 하위 명령이 있습니다. `systemctl --help` 에서 ''dependencies'' 를 찾아 보세요. 대상은 `graphical.target` 이고 페이저는 `--no-pager` 로 끕니다.', 'systemctl list-dependencies graphical.target --no-pager > /tmp/q6.txt
head -8 /tmp/q6.txt

# graphical.target 아래에 multi-user.target 이 있고, 그 아래에 basic.target 등이 더 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf\\nsystemctl set-default graphical.target >/dev/null 2>&1\\n"]', '["sh", "-c", "( [ -s /tmp/q6.txt ] ) && ( head -1 /tmp/q6.txt | grep -q graphical.target ) && ( grep -q multi-user.target /tmp/q6.txt ) && ( grep -q basic.target /tmp/q6.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q6.txt ]"]}, {"label": "첫 줄이 graphical.target 이다", "cmd": ["sh", "-c", "head -1 /tmp/q6.txt | grep -q graphical.target"]}, {"label": "multi-user.target 이 의존 목록에 있다", "cmd": ["sh", "-c", "grep -q multi-user.target /tmp/q6.txt"]}, {"label": "basic.target 이 있다", "cmd": ["sh", "-c", "grep -q basic.target /tmp/q6.txt"]}]', '[{"title": "systemd.special: target 유닛 설명", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.special.html"}, {"title": "journalctl 매뉴얼", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}, {"title": "bootup: 부팅 과정", "url": "https://www.freedesktop.org/software/systemd/man/latest/bootup.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 7, 'rescue 와 emergency 는 무엇이 다를까', '부팅 장애 때 쓰는 특별한 target 이 둘 있습니다. `rescue.target` 과 `emergency.target` 입니다. 설명으로 가장 알맞은 것은 무엇일까요?', '둘 다 root 비밀번호를 묻는 최소한의 상태이지만, 파일시스템을 얼마나 연결해 주는지가 다릅니다.', NULL, NULL, '[]', 'choice', '["`rescue` 는 기본 시스템과 파일시스템 마운트까지 올린 단일 사용자 상태, `emergency` 는 루트 파일시스템만 읽기 전용으로 붙인 가장 최소한의 상태다", "`rescue` 는 네트워크와 모든 서비스가 켜진 정상 상태, `emergency` 는 서비스 일부만 끈 상태다", "`rescue` 는 디스크를 포맷해 초기화하는 모드, `emergency` 는 부팅 로그를 지우는 모드다", "`rescue` 는 원격으로, `emergency` 는 서버 앞에서만 쓸 수 있는 모드다"]', 0, '`rescue.target` 은 기본 시스템(`sysinit.target`)까지 올리고 파일시스템을 마운트한 뒤 root 셸을 줍니다(단일 사용자 모드). `emergency.target` 은 루트 파일시스템만 읽기 전용으로 마운트하고 거의 아무것도 시작하지 않는, 가장 작은 상태입니다. 마운트 설정(`/etc/fstab`) 오류로 정상 부팅이 안 될 때는 마운트 단계에서 막히므로 emergency 가 뜨는 경우가 많고, 이때 파일을 고치려면 `mount -o remount,rw /` 로 쓰기 가능하게 바꿔야 합니다. 둘 다 파일을 지우는 모드가 아니며, 접근 방법은 콘솔·GRUB 파라미터 등 같습니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 8, 'target 을 바꾸는 두 가지 방법', '`multi-user.target` 으로 target 을 바꾸는 두 방법입니다. 빈칸을 채우세요.
- 지금 **당장** 그 target 으로 전환한다 (필요 없는 유닛은 멈춘다. 장애 대응 때 `rescue.target` 으로 쓰기도 함)
- **다음 부팅부터** 기본으로 쓴다', '당장 전환하는 하위 명령은 "(다른 것에서) 떼어 놓다"는 뜻의 영어 단어입니다. 다음 부팅의 기본값은 앞서 직접 해 본 명령입니다.', NULL, NULL, '[]', 'fill', '["isolate", "set-default", "get-default", "enable", "daemon-reload", "mask"]', NULL, '`systemctl isolate X.target` 은 X 와 그 의존 대상만 남기고 나머지 유닛을 멈추며 즉시 전환합니다(재부팅 없음). 접속한 세션이 끊길 수 있어 원격에서는 신중해야 합니다. `set-default` 는 지금 상태는 바꾸지 않고 다음 부팅의 기본값만 바꿉니다. `get-default` 는 읽기 전용이고, `enable` 은 서비스를 부팅 때 시작하게 하는 명령이며 target 의 기본값 지정에 쓰지 않습니다.', '[0, 1]', 'systemctl {0} multi-user.target
systemctl {1} multi-user.target', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 9, '부팅 로그에서 오류만 골라 보기', '부팅 후 서비스 문제를 찾을 때는 `journalctl -b` 로 **이번 부팅의 로그**를 보고, `-p` 로 **우선순위**를 걸러 오류만 봅니다. 이 서버에 일부러 오류 한 줄과 정보 한 줄(`bootdemo` 라는 이름표)이 남겨져 있습니다.

**이번 부팅에서 오류(`err`) 이상**의 로그만 **`/tmp/q9.txt`** 에 저장하세요. 오류 줄 `disk check failed` 는 들어가고, 정보 줄 `all fine` 은 들어가지 않아야 합니다. (`--no-pager` 로 페이저를 끕니다.)', '`journalctl` 에 "이번 부팅"을 뜻하는 `-b` 와 우선순위를 거르는 `-p 이름` 을 함께 씁니다. 우선순위 이름은 `emerg`, `alert`, `crit`, `err`, `warning`, `notice`, `info`, `debug` 가 있습니다. 어느 이름이 "오류"인지 골라 보세요.', 'journalctl -b -p err --no-pager > /tmp/q9.txt
grep bootdemo /tmp/q9.txt

# -p err 는 err 이상(err, crit, alert, emerg)만 보여 준다. info 수준의 all fine 은 빠진다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf\\nsystemctl set-default graphical.target >/dev/null 2>&1\\nlogger -p user.err -t bootdemo ''disk check failed''\\nlogger -p user.info -t bootdemo ''all fine''\\nsleep 1\\njournalctl -b -p err --no-pager | grep -q bootdemo || sleep 2\\n"]', '["sh", "-c", "( [ -s /tmp/q9.txt ] ) && ( grep -q \\"disk check failed\\" /tmp/q9.txt ) && ( ! grep -q \\"all fine\\" /tmp/q9.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q9.txt ]"]}, {"label": "오류 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"disk check failed\\" /tmp/q9.txt"]}, {"label": "정보 줄은 빠졌다", "cmd": ["sh", "-c", "! grep -q \\"all fine\\" /tmp/q9.txt"]}]', '[{"title": "systemd.special: target 유닛 설명", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.special.html"}, {"title": "journalctl 매뉴얼", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}, {"title": "bootup: 부팅 과정", "url": "https://www.freedesktop.org/software/systemd/man/latest/bootup.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 10, '커널 메시지만 보기', '커널이 하드웨어(디스크·네트워크 카드 등)를 인식하는 과정의 메시지는 서비스 로그와 따로 봅니다. 부팅 중 디스크가 안 보이거나 장치 오류가 있을 때 가장 먼저 읽는 곳입니다.

`journalctl` 로 **커널 메시지만** 골라서 **`/tmp/q10.txt`** 에 저장하세요. 서비스가 남긴 `bootdemo` 줄은 들어가면 안 됩니다. (`--no-pager` 로 페이저를 끕니다. `dmesg` 도 같은 커널 메시지를 보여 주지만 이 문제는 `journalctl` 로 하세요.)', '`journalctl` 의 옵션 중 커널(kernel)의 첫 글자와 같은 짧은 옵션이 있습니다. 매뉴얼은 `journalctl --help` 에서 "kernel" 로 찾아보세요.', 'journalctl -k --no-pager > /tmp/q10.txt
head -3 /tmp/q10.txt

# -k 는 --dmesg 와 같다. 커널이 남긴 줄만 나오므로 서비스 로그(bootdemo)는 없다. dmesg 와 거의 같은 내용이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf\\nsystemctl set-default graphical.target >/dev/null 2>&1\\nlogger -p user.err -t bootdemo ''disk check failed''\\nsleep 1\\n"]', '["sh", "-c", "( [ -s /tmp/q10.txt ] ) && ( grep -qE ''^-- | kernel: '' /tmp/q10.txt ) && ( ! grep -q bootdemo /tmp/q10.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q10.txt ]"]}, {"label": "커널 메시지가 있다 (비어 있으면 머리글 줄)", "cmd": ["sh", "-c", "grep -qE ''^-- | kernel: '' /tmp/q10.txt"]}, {"label": "서비스 로그는 섞이지 않았다", "cmd": ["sh", "-c", "! grep -q bootdemo /tmp/q10.txt"]}]', '[{"title": "systemd.special: target 유닛 설명", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.special.html"}, {"title": "journalctl 매뉴얼", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}, {"title": "bootup: 부팅 과정", "url": "https://www.freedesktop.org/software/systemd/man/latest/bootup.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 11, '커널 파라미터 읽기', 'GRUB 은 커널을 올릴 때 **커널 파라미터**(커널에 넘기는 옵션)를 함께 넘깁니다. 예를 들어 `ro`(읽기 전용으로 루트 마운트), `quiet`(메시지 줄이기), `root=…`(루트 파일시스템 위치), `systemd.unit=rescue.target`(이번 부팅만 rescue 로 부팅) 같은 것들입니다. 장애 때 GRUB 화면에서 이 줄을 **한 번만 고쳐서** 복구 모드로 들어가기도 합니다.

지금 이 서버가 **부팅할 때 받은 커널 파라미터**를 **`/tmp/q11.txt`** 에 저장하세요. (편집이 아니라 읽기만 합니다.)', '실행 중인 커널은 부팅 때 받은 명령줄을 `/proc` 아래 가상 파일 한 곳에 보여 줍니다. 이름에 "명령줄(command line)" 이 들어갑니다. `cat` 으로 읽어 파일에 저장하세요.', 'cat /proc/cmdline > /tmp/q11.txt
cat /tmp/q11.txt

# /proc/cmdline 은 지금 돌고 있는 커널이 부팅 때 받은 파라미터. 파일(/etc/default/grub)이 아니라 실제로 넘어간 값이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ -s /tmp/q11.txt ] ) && ( [ \\"$(cat /tmp/q11.txt)\\" = \\"$(cat /proc/cmdline)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/q11.txt ]"]}, {"label": "지금 커널의 명령줄과 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q11.txt)\\" = \\"$(cat /proc/cmdline)\\" ]"]}]', '[{"title": "systemd.special: target 유닛 설명", "url": "https://www.freedesktop.org/software/systemd/man/latest/systemd.special.html"}, {"title": "journalctl 매뉴얼", "url": "https://www.freedesktop.org/software/systemd/man/latest/journalctl.html"}, {"title": "bootup: 부팅 과정", "url": "https://www.freedesktop.org/software/systemd/man/latest/bootup.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 541, 12, '서버가 부팅 중에 멈췄을 때 어디부터 볼까', '서버가 재부팅 후 로그인 화면까지 올라오지 못했습니다. 콘솔에는 `You are in emergency mode` 가 떠 있고, `Failed to mount /data` 같은 줄이 보입니다. 가장 알맞은 대응은 무엇일까요?', '증거부터 읽습니다. 실패한 마운트 이름이 로그에 나오고, 마운트 목록은 한 설정 파일에서 옵니다.', NULL, NULL, '[]', 'choice', '["원인을 모르니 서버를 바로 초기화하고 OS 를 다시 설치한다", "`systemctl set-default graphical.target` 을 실행하면 emergency 가 해제된다", "로그는 재부팅하면 모두 사라지니 읽을 수 없으므로 하드디스크를 새것으로 바꾼다", "root 로 들어가 `journalctl -b` 로 실패한 이유를 읽고, 마운트 설정 파일(`/etc/fstab`)의 해당 줄을 고친 뒤 다시 부팅한다"]', 3, '부팅 장애의 기본 순서는 (1) 어느 단계에서 멈췄는지 본다, (2) 로그(`journalctl -b`, 커널은 `-k`)에서 첫 오류를 찾는다, (3) 원인 파일을 고친다, (4) 다시 부팅해 확인한다 입니다. `Failed to mount` 가 보이면 `/etc/fstab` 의 장치 이름·UUID·옵션을 의심합니다. 기본 target 변경은 다음 부팅의 목표를 바꿀 뿐 emergency 의 원인을 고치지 않고, 로그는 저장 설정이 되어 있으면 이전 부팅(`journalctl -b -1`)도 읽을 수 있으며, 초기화·디스크 교체는 증거를 읽기 전에 선택할 일이 아닙니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 541 AND order_index = 12);
